window.REPORT_PRELOAD_CACHE["UPS.html"] = {"version":"37f31082c1dc876b36ac597dda342c305a4d8fd45c1e16ae65a22ddff9bdf92b","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>联合包裹服务 United Parcel Service, Inc. (NYSE: UPS) 深度研究报告：2026Q3营收增长6.7%、战略转型升级、B2B溢价与全年指引上调</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n upsbrown: {\n 300: '#D4B28C',\n 400: '#A36F3C',\n 500: '#351C15',\n 600: '#2A1510',\n 700: '#1F0F0B',\n },\n upsgold: {\n 400: '#FFC845',\n 500: '#FFB100',\n 600: '#E69F00',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(53, 28, 21, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #FFB100;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-upsgold-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-upsbrown-400 via-upsgold-500 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-upsbrown-500 to-upsgold-500 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n UPS\n </div>\n <div>\n <div class=\"text-[11px] text-upsgold-400 font-semibold tracking-wider uppercase\">NYSE: UPS · Global Logistics Leader</div>\n <div class=\"text-sm font-bold leading-tight\">联合包裹服务 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">UPS 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 商业模式与全球物流架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与核心护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 全球快递物流巨头横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与股息复利推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球供应链与快递物流研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / SEC 10-Q)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-upsbrown-500 via-upsbrown-600 to-upsgold-500 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-upsbrown-500/25\">\n UPS\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-upsgold-400 bg-upsbrown-500/25 px-2 py-0.5 rounded\">NYSE: UPS</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">联合包裹深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球快递与供应链物流绝对巨头 · Q3 营收增长 6.7%、优质 B2B/SMB 转型与全年指引上调\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$110.37 <span class=\"text-slate-400 text-[10px]\">($90.8-$122.4)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">Q3 2026 总营收</span>\n <span class=\"font-mono font-bold text-emerald-400\">$229 亿 <span class=\"text-slate-400\">(+6.7% YoY)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">股息收益率 (Dividend Yield)</span>\n <span class=\"font-mono font-bold text-upsgold-400\">~5.94% (季度派息 $1.64)</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-upsgold-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>商业模式与全球物流架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与核心护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>全球快递物流巨头横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与股息复利推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-upsgold-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-upsgold-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-upsbrown-500 to-upsbrown-600 hover:from-upsbrown-600 hover:to-upsbrown-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-upsbrown-500/15 text-upsbrown-700 dark:text-upsgold-300 font-bold border border-upsbrown-500/30\">评级：买入 / 高股息物流龙头与战略转型困境反转底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026Q3 业绩超预期、Amazon 业务重组完成与全年指引上调期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: UPS</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#FFB100 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-upsgold-500/20 border border-upsgold-400/40 text-upsgold-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-upsgold-400 animate-pulse\"></span>\n <span>CORE THESIS · Q3 营收 $229亿（+6.7% YoY）超预期 × 美国国内营业利润大增 14.3% × 顺利消化最大客户减量，全面聚焦高利润 SMB 与 B2B 组合</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 联合包裹服务 United Parcel Service, Inc. (NYSE: UPS) 深度研究报告：全球物流巨头转型升级、Q3业绩超预期与高股息投资价值分析\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 全球快递与供应链物流绝对巨头 <strong class=\"text-white\">联合包裹服务（UPS）</strong>交出了一份强劲的 <strong class=\"text-white\">2026 财年第三季度财报</strong>：合并营收达到 <strong class=\"text-upsgold-300\">$229 亿美元（同比增长 6.7%）</strong>，所有三大业务板块（美国国内、国际、供应链解决方案）均实现营收正增长 [cite: 1.2.1]。\n 随着最大客户（Amazon）计划性减量在 2026 年上半年顺利平稳完成，UPS 成功将运力转向高利润的中小企业（SMB）与高端 B2B/医疗物流，驱动美国国内营业利润大增 14.3%，运营利润率提升至 7.0% [cite: 1.2.1, 1.2.4, 1.2.5]。基于强劲的业务势头，公司上调了全年营收（~$92.6B）、营业利润（~$8.75B）及自由现金流目标（~$6.1B） [cite: 1.2.1]，并维持高达 <strong class=\"text-emerald-400\">~5.94% 的高股息收益率</strong> [cite: 1.1.1]。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">Q3 营收与利润超越预期</div>\n <div class=\"text-white font-semibold\">Q3 合并营收 $22.9B（+6.7% YoY），非 GAAP 调整后稀释 EPS 达 $1.69，各板块全线正增长 [cite: 1.2.1]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">国内业务质效双升</div>\n <div class=\"text-upsgold-300 font-semibold\">美国国内营业利润大增 14.3%，单件营收（RPP）增长 6.1%，SMB 占比提升至 35.1% 历史新高 [cite: 1.2.1, 1.2.4]</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">全面上调全年财务指引</div>\n <div class=\"text-emerald-400 font-semibold\">上调全年营收至 ~$92.6B、非 GAAP 营业利润至 ~$8.75B 及自由现金流目标至 ~$6.1B [cite: 1.2.1]</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>参考股价与市值</span>\n <span class=\"p-1.5 rounded-lg bg-upsbrown-500/15 text-upsbrown-600 dark:text-upsgold-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$94.0B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$110.37</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 全球物流快递龙头，总市值约 940 亿美元，伴随盈利拐点确立，估值修复空间显现。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 2026 合并营收</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$22.9B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+6.7% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 单季合并营收达 229 亿美元，三大核心业务板块全线实现营收正增长 [cite: 1.2.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 调整后 EPS 与 利润率</span>\n <span class=\"p-1.5 rounded-lg bg-upsgold-500/15 text-upsgold-600 dark:text-upsgold-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.69</span>\n <span class=\"text-xs font-bold text-upsgold-600 dark:text-upsgold-400 bg-upsgold-500/15 px-2 py-0.5 rounded\">非GAAP调整后</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n Q3 非 GAAP 调整后稀释每股收益达 $1.69，合并营业利润率（非 GAAP 调整后）达到 9.0% [cite: 1.2.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>股息收益率 (Dividend Yield)</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~5.94%</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">季度派息 $1.64</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 提供高达近 6% 的丰厚股息回报，季度例行派息维持在每股 $1.64，深受全球价值与 income 投资者青睐 [cite: 1.1.1, 1.2.1]。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 商业模式与全球物流架构 (Business Model & Global Logistics Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-upsbrown-600 dark:text-upsgold-400\">Section 01 · Business Model & Global Logistics Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 商业模式与全球物流架构：美国国内快递、国际快递与供应链解决方案</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY2026E 总营收 ~$92.6B · 覆盖全球 200+ 国家和地区</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2022–2026E 全球合并营收与非GAAP调整后营业利润趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">顺利消化最大客户减量后，营收稳步回升至 926 亿美元，盈利能力结构性修复</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_mix')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-upsbrown-600 dark:text-upsgold-400 shadow-sm transition cursor-pointer\">视图A：合并营收与营业利润</button>\n <button onclick=\"switchBizChart('segment_metrics')\" id=\"btn-chart-seg\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：Q3 三大核心板块营收拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">UPS 三大核心业务板块与 Q3 表现</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-upsbrown-500/15 text-upsbrown-600 dark:text-upsgold-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">美国国内包裹业务（U.S. Domestic Package）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 营收增长 4.5%（单件营收 RPP 增长 6.1%）。主动缩减低利润的 Amazon 订单后，高毛利 SMB（中小企业）占比提升至 35.1% 历史新高，营业利润大增 14.3% [cite: 1.2.1, 1.2.4]。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">国际包裹业务（International Package）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 营收增长 7.1%（单件营收 RPP 增长 15.0%），营业利润率高达 14.9%。受益于亚洲至美国及亚洲内部贸易航线强劲，盈利能力超越市场预期 [cite: 1.2.1, 1.2.4]。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-upsgold-500/15 text-upsgold-600 dark:text-upsgold-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">供应链解决方案（Supply Chain Solutions）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 营收大增 18.2%，主要由货运代理（Forwarding）、物流及医疗保健物流（Healthcare logistics）的高速增长驱动，成为多元化增长引擎 [cite: 1.2.1, 1.2.4]。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">全年业绩指引上调</span>\n <span class=\"font-bold text-upsbrown-600 dark:text-upsgold-400\">营收 ~$92.6B · 营业利润 ~$8.75B · 自由现金流 ~$6.1B [cite: 1.2.1]</span>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-upsbrown-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-upsbrown-500/15 text-upsbrown-700 dark:text-upsgold-300 text-xs font-bold\">国内转型成功 · SMB占比达 35.1%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">U.S. Domestic Strategy</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. “Better Not Bigger” 策略与 SMB 客户崛起</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 尽管整体国内包裹量因主动减少亚马逊低利润订单而同比下降 3.3%，但剥离低质量大客户后，中小企业（SMB）与高端企业客户量逆势增长 1.8%（SMB 专供增长 3.7%），使 SMB 成为总国内体量的中流砥柱 [cite: 1.2.4]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>SMB 占比达到 35.1% 历史新高</span>\n <span class=\"text-upsbrown-600 dark:text-upsgold-400 font-semibold\">单件营收 RPP 强劲增长 6.1%</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 text-xs font-bold\">高毛利医疗与物流 · SCS大增 18.2%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">Healthcare & Logistics</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. 供应链解决方案与医疗物流爆发</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 供应链解决方案板块（SCS）在 Q3 录得 18.2% 的强劲营收增长。其中医疗保健（Healthcare）物流业务连续多个季度实现全板块全线增长，营收体量稳步突破 30 亿美元大关，成为高附加值增长极 [cite: 1.2.1, 1.2.4]。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>SCS 营收同比增长 18.2%</span>\n <span class=\"text-emerald-600 dark:text-emerald-400 font-semibold\">医疗物流连续多季高增突破 $3B</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与核心护城河 (Industry Position & Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四大核心护城河：全球航空货运网络、综合转运枢纽与自动化降本</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球包裹与供应链绝对图腾)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-upsbrown-500/15 text-upsbrown-600 dark:text-upsgold-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球庞大的专有航空货运机队与转运枢纽</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 拥有数百架宽体货机和全球超级转运中心（如路易斯维尔 Worldport），构筑了任何竞争对手数十年内难以复刻的空地一体化全球转运网络。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">行业领先的自动化与网络运营效率</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 依托历史最自动化、最高效的智能分拣网络，配合 Transform 战略持续削减成本（全年在轨实现 30 亿美元成本节约目标），不断释放运营利润率 [cite: 1.2.1, 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-upsgold-500/15 text-upsgold-600 dark:text-upsgold-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">B2B 与中小企业（SMB）深度品牌粘性</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 历经数十年的供应链信誉沉淀，UPS 在商业客户和高粘性 SMB 中建立了极强的品牌心智，为其抵御宏观波动提供了坚实保障 [cite: 1.2.4]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">卓越的高股息分红传统（近 6% 收益率）</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 凭借百亿级的自由现金流转化能力（2026 年 FCF 目标 ~$6.1B） [cite: 1.2.1]，长期维持高比例现金分红，成为全球机构投资者的优质压舱石 [cite: 1.1.1]。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">全球快递物流巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">UPS vs 联邦快递 (FDX) vs 敦豪 (DHL)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 全球快递物流巨头横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-upsbrown-600 dark:text-upsgold-400\">Section 03 · Global Express & Logistics Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 全球快递物流巨头横向对比：UPS B2B与医疗优势 vs 联邦快递综合航空网络</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-upsbrown-500 text-white shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('express')\" data-filter=\"express\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">全球快递物流双雄 (UPS/FDX)</button>\n <button onclick=\"filterCompetitors('global')\" data-filter=\"global\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">国际货运巨头 (DHL)</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心主营业务</th>\n <th class=\"py-4 px-4 min-w-[140px]\">最新季度营收规模</th>\n <th class=\"py-4 px-4 min-w-[100px]\">股息收益率</th>\n <th class=\"py-4 px-4 min-w-[115px]\">运营与利润特点</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与竞合定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"express\" class=\"bg-upsbrown-500/5 dark:bg-upsbrown-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-upsbrown-600 text-white text-[10px] font-extrabold\">全球快递巨头</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">联合包裹 (UPS)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">United Parcel Service</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">美国国内包裹 + 国际快递 + 供应链物流</td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">$22.9 亿 (Q3) [cite: 1.2.1]</td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">~5.94% (高股息) [cite: 1.1.1]</td>\n <td class=\"py-4 px-4 font-mono font-bold text-upsbrown-600 dark:text-upsgold-400\">合并利润率 9.0% [cite: 1.2.1]</td>\n <td class=\"py-4 px-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>B2B与医疗物流霸主：</strong>主动剥离低利电商订单后全面聚焦 SMB 与高利润医疗供应链，自由现金流与股息回报极具吸引力。\n </td>\n </tr>\n\n <tr data-category=\"express\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">联邦快递 (FDX)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">FedEx Corporation</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">快递、空运、地运及地面货运网络</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">规模约 ~$22B+/季</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~2.0%–2.5%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">网络整合中</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>航空快递网络先驱：</strong>正积极推进“Drive”网格整合计划将地面与航空网络合一，与 UPS 在全美市场展开激烈份额争夺。\n </td>\n </tr>\n\n <tr data-category=\"global\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">敦豪集团 (DHL Group)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Deutsche Post DHL</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全球货运代理、欧洲快递及邮政物流</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">体量庞大 (欧亚领先)</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~3.0%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">欧洲公用属性</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>欧洲与跨境货运巨头：</strong>在欧洲本土及亚欧跨国货运代理领域占据绝对优势，但在美国国内市场份额逊于 UPS 与 FDX。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球快递物流同行股息收益率（Dividend Yield）与利润率对照</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">UPS 凭借近 6% 的股息收益率在交通运输与物流板块中树立了顶级 income 资产标杆</p>\n </div>\n <span class=\"text-xs font-semibold text-upsbrown-700 dark:text-upsgold-300 bg-upsbrown-500/15 px-2.5 py-1 rounded\">~5.94% 顶级股息收益率</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与股息复利推演 (Financial Health & Dividend Compounding Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Dividend Compounding Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与股息复利体系：$61亿自由现金流、季度派息与 6% 收益率</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">全年自由现金流目标 ~$6.1B [cite: 1.2.1] · 季度派息 $1.64/股 [cite: 1.2.1]</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-upsbrown-600 dark:text-upsgold-400 uppercase\">Free Cash Flow Target</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$6.1B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 全年非 GAAP 调整后自由现金流目标上调至约 61 亿美元，资本开支保持在约 30 亿美元的合理区间 [cite: 1.2.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Quarterly Dividend</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$1.64/股</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 例行派发每股 $1.64 的季度现金股息（全年分红总额预计约 $54 亿美元），提供极强的现金流支撑 [cite: 1.2.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-upsgold-600 dark:text-upsgold-400 uppercase\">Dividend Yield</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~5.94%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 静态测算下分红收益率高达近 6%，在蓝筹工业股中名列前茅，是长线配置现金流资产的绝佳标的 [cite: 1.1.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Operating Cash Flow (9M)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$5.99B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 年初至今前九个月经营活动现金流达到 59.86 亿美元（去年同期 $5.15B），现金造血质量显着提升 [cite: 1.2.5]。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2021–2026E 全球合并营收与自由现金流演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">经历最大客户减量阵痛后，营收在 2026 年重回增长轨道，自由现金流迈向 61 亿美元高位</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-upsbrown-700 dark:text-upsgold-300 bg-upsbrown-500/15 px-2.5 py-1 rounded\">现金流与股息复利支撑曲线</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-upsgold-400 font-bold\">\n <span>UPS COMPOUNDING SIMULATOR · 联合包裹长线持仓与股息再投资推演器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">UPS 长期持仓复利与高股息自动再投资 (DRIP) 动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 ~$110.37 | 预期股息率 ~5.94% | 模拟多年期资本增值与高股息雪球模型</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-upsbrown-500/15 border border-upsbrown-400/30 text-xs font-semibold text-upsgold-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#FFB100] cursor-pointer\">\n <span>开启股息自动再投资 (DRIP 复利)</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始模拟投资额 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#FFB100] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">5 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"5\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#FFB100] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">预期股价年化增长率 (Price CAGR)</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">7.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"0\" max=\"18\" step=\"0.5\" value=\"7.0\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">远期估值多维回报情景：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(5)\" data-tax=\"5\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-upsgold-400 transition cursor-pointer\">\n 5% 保守增长<br><span class=\"text-[10px] text-slate-400\">宏观震荡期</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(7)\" data-tax=\"7\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-upsbrown-500 text-white border border-upsgold-400 shadow transition cursor-pointer\">\n 7% 合理中枢<br><span class=\"text-[10px] text-slate-200\">转型复苏均值</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(10)\" data-tax=\"10\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-upsgold-400 transition cursor-pointer\">\n 10% 进取增长<br><span class=\"text-[10px] text-slate-400\">B2B与医疗牛市</span>\n </button>\n </div>\n </div>\n </div>\n\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计投资资产估值 (USD)</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$55,140</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +83.8% (含 6% 现金分红再投资)</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末年化现金分红总额 (USD)</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-upsgold-300 mt-1.5\">~$3,270</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">丰厚的高股息被动现金流入</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末对应估值多维年化回报率 (CAGR)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">13.0%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">总回报复合年化增长率</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末持仓总份额预估</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400\">352.4 股</div>\n <div class=\"text-shares-end text-xs text-slate-400 mt-1.5\">DRIP 滚雪球持续增厚股数</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">Q3 营收 +6.7% + 利润率回升至 9%</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Q3 业绩超预期并上调指引：</strong>合并营收大增 6.7% 至 $22.9B，国内营业利润劲增 14.3%，全面上调全年营收、营业利润及 FCF 目标 [cite: 1.2.1, 1.2.4]。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>成功完成战略转型调整：</strong>平稳消化最大客户 Amazon 减量，将运力腾挪给高利润的 SMB（占比创 35.1% 历史新高）与医疗供应链 [cite: 1.2.4, 1.2.5]。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>近 6% 顶级的股息收益率：</strong>提供高达 ~5.94% 的丰厚派息支持，满足价值型与 Income 投资者的核心现金流配置需求 [cite: 1.1.1]。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">宏观快递需求波动 + 劳动力与薪酬成本</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>宏观经济与零售货量弹性：</strong>尽管 Q3 表现亮眼，但整体零售快递需求仍受宏观通胀及消费者支出偏好的温和制约。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>劳动力与团队薪酬成本压力：</strong>作为重资产、劳动力密集型企业，宏观薪酬和福利成本变化对运营利润率存在潜在约束。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>国际业务地缘政治扰动：</strong>国际快递与供应链板块面临国际贸易政策与地缘政治因素的阶段性不确定性。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-upsbrown-600 dark:text-upsgold-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景目标价推演与高股息策略</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：高股息物流龙头底仓 · 逢回调稳健布局</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">18x–20x P/E ($135–$150)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>SMB 与医疗物流拓展速度超预期，Transform 战略全额兑现成本节约；利润率重回双位数，市场给予优质高股息蓝筹估值重估。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 潜在年化总回报：+20% 至 +28%（含近 6% 股息）\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-upsbrown-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-upsbrown-500/15 text-upsbrown-700 dark:text-upsgold-300 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-upsbrown-600 dark:text-upsgold-400\">概率：55%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">14x–16x P/E ($115–$128)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>2026–2028 稳步兑现上调后的全年指引（营收 ~$92.6B、营业利润 ~$8.75B） [cite: 1.2.1]；估值稳定在 15x 左右历史合理中枢。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-upsbrown-600 dark:text-upsgold-400\">\n 稳健年化总回报：+12% 至 +16%（基本面修复 + 6% 股息）\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">11x–12x P/E ($88–$98)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观经济疲软导致整体快递包裹量下滑，成本控制不及预期，估值倍数受到传统运输板块情绪压制。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在回撤风险：-12% 至 -20%（近 6% 高股息提供安全垫）\n </div>\n </div>\n </div>\n\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险与跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 宏观消费支出与包裹总量增速</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">电商与零售快递货量的宏观弹性</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管 B2B 与 SMB 转型成功，但整体快递包裹需求仍与北美及全球宏观零售景气度深度挂钩。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 劳动力成本与团队薪酬协议</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">一线派送员与仓储人员薪酬福利变动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 作为劳动力密集型重资产企业，薪酬福利和工会成本对长期运营利润率的边际影响需要持续监控。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-upsbrown-500/10 text-upsbrown-600 dark:text-upsgold-400 text-xs font-bold\">03 · 峰季（Peak Season）吞吐与效率</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">第四季度节假日高峰期的执行效率</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n Q4 节日季通常是全年利润的关键窗口，需关注自动化网络在峰季的高峰吞吐与成本控制表现 [cite: 1.2.1]。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">04 · 国际贸易与地缘政治扰动</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">跨境贸易航线与关税政策影响</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 国际业务与供应链解决方案板块涉及复杂的跨国航线，需关注全球贸易政策及汇率波动风险。\n </p>\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-upsgold-300 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与高股息策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 高股息防御与现金流底仓</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 将 UPS 定位为兼具公用事业防通胀属性与高股息回报（~6% 收益率）的核心底仓，提供极佳的组合现金流入 [cite: 1.1.1]。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-upsgold-300 mb-1\">2. 股价回调左侧建仓锚点</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 鉴于物流转型期股价随宏观情绪波动，若短期因市场震荡回调至 <strong>$100–$105 区间</strong>，建议分批增持。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 资产配置税务与长线持有</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 优先在长线账户中配置，充分享受 UPS 从传统电商快递向高利润 SMB 与医疗物流转型带来的估值修复。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-upsbrown-500/15 text-upsbrown-700 dark:text-upsgold-300 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续校验 UPS 营收增长、营业利润率与自由现金流：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FFB100]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 合并营收达成全年 ~$92.6B 指引（如 Q3 增长 6.7% 至 $22.9B） [cite: 1.2.1]</span>\n <span class=\"text-[11px] font-mono text-upsbrown-600 dark:text-upsgold-400 font-semibold shrink-0\">核心营收增长锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检查每季财报营收是否稳健达成全年 ~926 亿美元指引，验证业务回暖趋势 [cite: 1.2.1]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FFB100]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 美国国内业务营业利润大幅改善（如 Q3 飙升 14.3%） [cite: 1.2.1]</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">国内盈利质量</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪美国国内板块营业利润率（Q3 达 7%）及单件营收（RPP）增长 [cite: 1.2.1, 1.2.4]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FFB100]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 全年自由现金流达成 ~$6.1B 目标 [cite: 1.2.1]</span>\n <span class=\"text-[11px] font-mono text-upsgold-600 dark:text-upsgold-400 font-semibold shrink-0\">现金造血保障</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检验全年自由现金流是否如期达成 ~61 亿美元，确保股息派发安全 [cite: 1.2.1]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FFB100]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 中小企业（SMB）客户占比保持在 35%+ 高位</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">客户结构优化</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督 SMB 占比（当前 35.1%）及高毛利客户交付份额，确认“Better Not Bigger”成效 [cite: 1.2.4]。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FFB100]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 供应链解决方案（SCS）与医疗物流持续高增（突破 $3B） [cite: 1.2.4]</span>\n <span class=\"text-[11px] font-mono text-upsbrown-600 dark:text-upsgold-400 font-semibold shrink-0\">多元化增长引擎</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估医疗保健与货运代理业务的季度营收贡献，确认非包裹业务增长动能。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FFB100]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 季度现金分红（$1.64/股）稳定发放与高股息回报 [cite: 1.2.1]</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">股息回报落实</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确认每季度例行现金分红按时派发，维护 ~6% 的高股息收益率 [cite: 1.1.1, 1.2.1]。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>联合包裹服务 United Parcel Service, Inc. (NYSE: UPS) 深度商业与投资价值分析报告 · 机构研究框架版 [cite: 1.2.1]</span>\n <span>数据基准：2026Q3 财报 (SEC Form 10-Q) 及 2026 年 11 月市场一致预期 [cite: 1.2.1, 1.2.5]</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于 UPS 公开财务报告（10-Q/10-K）、2026Q3 财报业绩公告及全球物流快递行业调研资料整理生成，旨在提供结构化的产业分析与龙头估值框架。报告中涉及的盈利预测、现金流指引、三情景目标价及复利模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-upsgold-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-upsgold-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-upsbrown-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-upsbrown-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === 'express' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n let currentMultiple = 7;\n\n function setTaxRate(mult) {\n currentMultiple = mult;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnMult = parseFloat(btn.dataset.tax);\n if (Math.abs(btnMult - mult) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-upsbrown-500 text-white border border-upsgold-400 shadow transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-200';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-upsgold-400 transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-400';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n const drip = document.getElementById('drip-toggle').checked;\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initialPrice = 110.37;\n const annualDivPerShare = 6.56; // $1.64 * 4\n const g = growthPct / 100;\n\n let shares = principal / initialPrice;\n let currentPrice = initialPrice;\n let totalDividendsCollected = 0;\n\n for (let i = 0; i < years; i++) {\n currentPrice *= (1 + g);\n let annualDiv = shares * annualDivPerShare;\n totalDividendsCollected += annualDiv;\n if (drip) {\n shares += annualDiv / currentPrice;\n }\n }\n\n let finalPortfolioVal = shares * currentPrice;\n let totalReturnPct = ((finalPortfolioVal - principal) / principal) * 100;\n let cagr = (Math.pow(finalPortfolioVal / principal, 1 / years) - 1) * 100;\n let endingAnnualDiv = shares * annualDivPerShare;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(finalPortfolioVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (含股息再投资)`;\n document.getElementById('sim-annual-div').textContent = '~$' + Math.round(endingAnnualDiv).toLocaleString('en-US');\n document.getElementById('sim-yoc').textContent = cagr.toFixed(1) + '%';\n document.getElementById('sim-cum-div').textContent = shares.toFixed(1) + ' 股';\n }\n\n const KPI_STORAGE_KEY = 'ups_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_mix';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const revConfig = {\n type: 'bar',\n data: {\n labels: ['2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n label: '合并总营收 ($B)',\n data: [100.3, 91.1, 91.1, 91.2, 92.6],\n backgroundColor: '#351C15',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n type: 'line',\n label: '调整后营业利润 ($B)',\n data: [13.1, 9.9, 8.5, 8.2, 8.75],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 2.5,\n pointRadius: 4,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 110,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 15,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n const segConfig = {\n type: 'bar',\n data: {\n labels: [\n '美国国内包裹营收 ($B)',\n '国际包裹营收 ($B)',\n '供应链解决方案营收 ($B)',\n 'Q3 合并总营收 ($B)'\n ],\n datasets: [\n {\n label: 'Q3 2026 各板块营收表现',\n data: [14.1, 4.4, 4.4, 22.9],\n backgroundColor: [\n '#351C15',\n '#FFB100',\n '#06B6D4',\n '#10B981'\n ],\n borderRadius: 6,\n barThickness: 26\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `板块营收: $${ctx.parsed.x}B`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 25,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_mix' ? revConfig : segConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnSeg = document.getElementById('btn-chart-seg');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_mix') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-upsbrown-600 dark:text-upsgold-400 shadow-sm transition cursor-pointer';\n btnSeg.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2022–2026E 全球合并营收与非GAAP调整后营业利润趋势';\n subEl.textContent = '顺利消化最大客户减量后，营收稳步回升至 926 亿美元，盈利能力结构性修复';\n } else {\n btnSeg.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-upsbrown-600 dark:text-upsgold-400 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-medium font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2026Q3 三大核心板块营收拆解';\n subEl.textContent = '美国国内包裹、国际包裹与供应链解决方案全线增长，合并营收达 $22.9B [cite: 1.2.1]';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '全球专有航空与转运网络',\n '自动化分拣与Transform降本',\n 'B2B与SMB客户深度粘性',\n '高股息现金回报 (~6%收益率)',\n '医疗与高附加值供应链协同'\n ],\n datasets: [\n {\n label: 'UPS (联合包裹)',\n data: [9.8, 9.4, 9.6, 9.7, 9.2],\n borderColor: '#351C15',\n backgroundColor: 'rgba(53, 28, 21, 0.24)',\n pointBackgroundColor: '#351C15',\n borderWidth: 2.5\n },\n {\n label: 'FedEx (联邦快递)',\n data: [9.7, 9.0, 9.0, 8.2, 8.5],\n borderColor: '#FFB100',\n backgroundColor: 'rgba(255, 177, 0, 0.14)',\n pointBackgroundColor: '#FFB100',\n borderWidth: 2.0\n },\n {\n label: 'DHL (敦豪集团)',\n data: [9.2, 8.5, 8.0, 8.0, 8.2],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.12)',\n pointBackgroundColor: '#10B981',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n 'UPS (联合包裹 · 高股息物流龙头)',\n 'FedEx (联邦快递 · 网络整合中)',\n 'DHL Group (敦豪 · 欧亚货运巨头)'\n ],\n datasets: [\n {\n label: '股息收益率 Dividend Yield (%)',\n data: [5.94, 2.20, 3.00],\n backgroundColor: '#351C15',\n borderRadius: 5,\n barThickness: 18\n },\n {\n label: '运营利润率 Operating Margin (%)',\n data: [9.0, 7.5, 5.0],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 18\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 10,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '合并总营收 ($ 亿美元)',\n data: [97.3, 100.3, 91.1, 91.1, 91.2, 92.6],\n backgroundColor: 'rgba(53, 28, 21, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后营业利润 ($ 亿美元)',\n data: [13.1, 13.1, 9.9, 8.5, 8.2, 8.75],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 120,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '合并总营收 ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 20,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '调整后营业利润 ($B)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>"};
